598	func (req CreateAuthorizationRequest) validatePresent() error {
599		missing := []string{}
600		if strings.TrimSpace(req.Operator) == "" {
601			missing = append(missing, "operator")
602		}
603		if strings.TrimSpace(req.Reason) == "" {
604			missing = append(missing, "reason")
605		}
606		if strings.TrimSpace(req.RequestID) == "" {
607			missing = append(missing, "request_id")
608		}
609		if strings.TrimSpace(req.AuthID) == "" {
610			missing = append(missing, "auth_id")
611		}
612		if strings.TrimSpace(req.ItemID) == "" {
613			missing = append(missing, "item_id")
614		}
615		if strings.TrimSpace(req.TrusteeID) == "" {
616			missing = append(missing, "trustee_id")
617		}
618		if strings.TrimSpace(req.ToID) == "" {
619			missing = append(missing, "to_id")
620		}
621		if strings.TrimSpace(req.ExpectedOwner) == "" {
622			missing = append(missing, "expected_owner")
623		}
624		if req.ExpectedVer <= 0 {
625			missing = append(missing, "expected_version")
626		}
627		if req.ExpiresAt.IsZero() {
628			missing = append(missing, "expires_at")
629		}
630		if len(missing) > 0 {
631			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
632		}
633		if req.Price < 0 {
634			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
635		}
636		return nil
637	}
638	
639	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
640		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
641		// 仍可回放；改价则按请求号冲突拒绝。
642		b, _ := json.Marshal(struct {
643			Kind          string `json:"kind"`
644			AuthID        string `json:"auth_id"`
645			ItemID        string `json:"item_id"`
646			TrusteeID     string `json:"trustee_id"`
647			ToID          string `json:"to_id"`
648			ExpectedOwner string `json:"expected_owner"`
649			ExpectedVer   int64  `json:"expected_version"`
650			ExpiresAt     string `json:"expires_at"`
651			Price         int64  `json:"price,omitempty"`
652			Reason        string `json:"reason"`
653		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
654			req.ExpectedOwner, req.ExpectedVer,
655			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
656		return string(b)
657	}
658	
659	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
660	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
661	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
662	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
663	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
664	//
665	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
666	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
667	// 参数错误与引用不存在不占用请求号。
668	//
669	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
670	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
671	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
672	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
673	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
674	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
675	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
676	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
677	// 错误（首次重提不标回放），状态已满足请求则正常创建。
678	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
679		if err := req.validatePresent(); err != nil {
680			return CreateAuthorizationResult{}, err
681		}
682		r.mu.Lock()
683		defer r.mu.Unlock()
684		if err := r.checkOpen(); err != nil {
685			return CreateAuthorizationResult{}, err
686		}
687	
688		now := r.now()
689		key := requestKey(req.Operator, req.RequestID)
690		sig := createAuthzParamsSig(req)
691		if prev, ok := r.state.Requests[key]; ok {
692			return r.replayCreateAuthz(prev, sig)
693		}
694	
695		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
696			if !isValidationErr(bizErr) {
697				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
698				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
699				r.state.Requests[key] = request{
700					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
701					Params: sig, Rejected: true, Reason: errCode(bizErr),
702					AuthID: req.AuthID, ItemID: req.ItemID,
703				}
704				if err := r.commit(); err != nil {
705					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
706					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
707					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
708					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
709					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
710					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
711					// 为零、不标回放、结果中业务错误为空，error 保留实际
712					// 写入错误。
713					delete(r.state.Requests, key)
714					return CreateAuthorizationResult{}, err
715				}
716			}
717			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
718		}
719	
720		h := r.state.Holdings[req.ItemID]
721		a := authzRec{
722			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
723			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
724			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
725		}
726		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
727		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
728		// 一次成功保存都会把这份未保存的授权带进登记册。
729		prevAuthSeq := r.state.NextAuthSeq
730		prevEvents := len(r.state.AuthEvents)
731		r.state.Authzs[req.AuthID] = a
732		authSeq := prevAuthSeq + 1
733		r.state.NextAuthSeq = authSeq
734		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
735			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
736			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
737			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
738		})
739		r.state.Requests[key] = request{
740			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
741			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
742		}
743		if err := r.commit(); err != nil {
744			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
745			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
746			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
747			if _, ok := r.state.Requests[key]; ok {
748				delete(r.state.Requests, key)
749				delete(r.state.Authzs, req.AuthID)
750				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
751				r.state.NextAuthSeq = prevAuthSeq
752			}
753			return CreateAuthorizationResult{}, err
754		}
755		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
756	}
757	
758	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
759		h, ok := r.state.Holdings[req.ItemID]
760		if !ok {
761			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
762				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
763			}
764			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
765		}
766		op, ok := r.state.Accounts[req.Operator]
767		if !ok {
768			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
769		}
770		trustee, ok := r.state.Accounts[req.TrusteeID]
771		if !ok {
772			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
773		}
774		to, ok := r.state.Accounts[req.ToID]
775		if !ok {
776			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
777		}
778		if req.TrusteeID == req.Operator {
779			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
780		}
781		if req.ToID == req.Operator {
782			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
783		}
784		if !op.Active {
785			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
786		}
787		if !trustee.Active {
788			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
789		}
790		if !to.Active {
791			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
792		}
793		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
794		if _, exists := r.state.Authzs[req.AuthID]; exists {
795			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
796		}
797		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
798		if !req.ExpiresAt.After(now) {
799			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
800				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
801		}
802		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
803			req.Operator != h.OwnerID {
804			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
805				ErrConflict, req.ItemID, h.OwnerID, h.Version)
806		}
807		return nil
808	}
809	
810	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
811		if prev.Kind != "auth_create" || prev.Params != sig {
812			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
813				ErrRequestConflict, prev.Operator, prev.RequestID)
814		}
815		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
816			Status: AuthActive, Replayed: true}
817		if prev.Rejected {
818			res.Err = codeErr(prev.Reason)
819			return res, res.Err
820		}
821		return res, nil
822	}
823	
824	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
825		b, _ := json.Marshal(struct {
826			Kind   string `json:"kind"`
827			AuthID string `json:"auth_id"`
828			Reason string `json:"reason"`
829		}{"auth_revoke", req.AuthID, req.Reason})
830		return string(b)
831	}
832	
833	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销
834	// （非授权人返回 ErrForbidden）；已使用的授权不能撤销
835	// （ErrAuthorizationUsed）。授权已撤销时再次撤销不新增授权变更记录，按
836	// 成功返回。到期但未使用的授权仍可撤销（变更记录从 expired 记为
837	// revoked）。请求号语义与其他操作一致。
838	//
839	// 无权（ErrForbidden）与已使用（ErrAuthorizationUsed）两类业务拒绝同样
840	// 需要落盘：拒绝结果尚未写入原登记册而保存失败（如数据位置暂时无法写入）
841	// 时，返回实际保存错误，不能只返回上述业务错误让调用者误以为拒绝结果已经
842	// 记住；结果为空（无授权编号、无状态、业务错误为空、不标回放），error 保留
843	// 保存失败的原因。这次未保存的拒绝不改变授权内容、授权变更记录、藏品当前
844	// 持有人和版本，也不占用操作者的本次请求号——即使保存失败后原登记册数据
845	// 暂时无法读取、状态未能按磁盘重建，未保存的拒绝也不能留在当前已打开的
846	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用同一操作者、
847	// 请求号、授权编号和原因重新提交，按当时的授权情况重新处理：拒绝条件仍存在
848	// 时先成功保存此次拒绝再返回相应业务错误（首次重提不标回放），此后完全相同
849	// 的提交才回放它；失败保存的请求不适用请求号冲突规则，该操作者用同号撤销另
850	// 一份自己有权撤销的授权时不会遭遇请求号冲突。必填内容缺失及授权不存在仍
851	// 直接按原错误拒绝、不占用请求号，不因当前无法保存而变成保存错误。
852	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
853		missing := []string{}
854		if strings.TrimSpace(req.Operator) == "" {
855			missing = append(missing, "operator")
856		}
857		if strings.TrimSpace(req.Reason) == "" {
858			missing = append(missing, "reason")
859		}
860		if strings.TrimSpace(req.RequestID) == "" {
861			missing = append(missing, "request_id")
862		}
863		if strings.TrimSpace(req.AuthID) == "" {
864			missing = append(missing, "auth_id")
865		}
866		if len(missing) > 0 {
867			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
868				ErrInvalidArgument, strings.Join(missing, ", "))
869		}
870		r.mu.Lock()
871		defer r.mu.Unlock()
872		if err := r.checkOpen(); err != nil {
873			return RevokeAuthorizationResult{}, err
874		}
875	
876		now := r.now()
877		key := requestKey(req.Operator, req.RequestID)
878		sig := revokeAuthzParamsSig(req)
879		if prev, ok := r.state.Requests[key]; ok {
880			return r.replayRevokeAuthz(prev, sig)
881		}
882	
883		a, ok := r.state.Authzs[req.AuthID]
884		if !ok {
885			// 引用不存在不占用请求号。
886			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
887			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
888		}
889		if a.GranterID != req.Operator {
890			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
891				ErrForbidden, a.GranterID, req.AuthID)
892			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
893				return RevokeAuthorizationResult{}, err
894			}
895			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
896		}
897		switch authzCurrentStatus(a, now) {
898		case AuthUsed:
899			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
900			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
901				return RevokeAuthorizationResult{}, err
902			}
903			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
904		case AuthRevoked:
905			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
906			// 相同请求重放回放同一结果。
907			r.state.Requests[key] = request{
908				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
909				Params: sig, AuthID: req.AuthID,
910			}
911			if err := r.commit(); err != nil {
912				return RevokeAuthorizationResult{}, err
913			}
914			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
915		}
916	
917		from := AuthActive
918		if authzCurrentStatus(a, now) == AuthExpired {
919			from = AuthExpired
920		}
921		a.Status = "revoked"
922		a.RevokedAt = now
923		r.state.Authzs[req.AuthID] = a
924		authSeq := r.state.NextAuthSeq + 1
925		r.state.NextAuthSeq = authSeq
926		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
927			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
928			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
929			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
930		})
931		r.state.Requests[key] = request{
932			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
933			Params: sig, AuthID: req.AuthID,
934		}
935		if err := r.commit(); err != nil {
936			return RevokeAuthorizationResult{}, err
937		}
938		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
939	}
940	
941	// recordRevokeRejection 登记撤销授权的状态类业务拒绝（非授权人的
942	// ErrForbidden、授权人撤销已使用授权的 ErrAuthorizationUsed）并落盘。
943	// 拒绝结果以保存完成为准：落盘失败时显式撤销尚未保存的请求号占用并返回
944	// 实际保存错误，调用方必须返回空结果与该错误，不能只返回业务拒绝让调用者
945	// 误以为拒绝已经记住；落盘成功时返回 nil，由调用方返回业务拒绝本身。
946	func (r *Registry) recordRevokeRejection(key, sig string, req RevokeAuthorizationRequest, bizErr error) error {
947		r.state.Requests[key] = request{
948			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
949			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
950		}
951		if err := r.commit(); err != nil {
952			// commit 失败时已尝试按磁盘内容重建状态，请求记录随之撤销；此处再
953			// 删一次以覆盖磁盘暂时不可读、状态未能重建的情形——未保存的拒绝
954			// 不能留在当前已打开的登记册中，也不能随随后另一次正常操作被保存。
955			delete(r.state.Requests, key)
956			return err
957		}
958		return nil
959	}
960	
961	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
962		if prev.Kind != "auth_revoke" || prev.Params != sig {
963			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
964				ErrRequestConflict, prev.Operator, prev.RequestID)
965		}
966		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
967		if prev.Rejected {
968			res.Err = codeErr(prev.Reason)
969			res.Status = ""
970			return res, res.Err
971		}
972		return res, nil
973	}
974	
975	func proxyTransferParamsSig(req ProxyTransferRequest) string {
976		b, _ := json.Marshal(struct {
977			Kind   string `json:"kind"`
978			AuthID string `json:"auth_id"`
979			Reason string `json:"reason"`
980		}{"proxy_transfer", req.AuthID, req.Reason})
981		return string(b)
982	}
983	
984	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
985	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
986	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
987	// 操作者记为实际受托账户并可通过授权编号追溯。
988	//
989	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
990	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
991	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
992	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
993	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
994	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
995	//
996	// 上述状态类拒绝以保存完成为准：拒绝结果尚未写入原登记册而保存失败（如
997	// 数据位置暂时无法写入）时，返回实际保存错误，不能只返回到期、无权或停用
998	// 等业务拒绝让调用者误以为这次拒绝已经记住；结果为空（不带授权或藏品编号、
999	// 不带转让和金额信息、不标回放，结果内的业务错误也为空），error 保留实际
1000	// 写入失败原因。这次未保存的拒绝不改变授权内容、使用标记、授权变更记录，
1001	// 也不改变藏品持有人、版本、转让历史与版税应付，并不占用操作者的本次请求
1002	// 号——即使保存失败后原数据暂时无法读取、状态未能按磁盘重建，未保存的拒绝
1003	// 也不能留在当前已打开的登记册中，或随随后另一次成功保存被记住。保存条件
1004	// 恢复后用完全相同的请求重提，按重提时的业务状态重新判断，而不是回放失败
1005	// 时的拒绝（例如到期拒绝保存失败、授权随后被撤销时，重提返回已撤销）；这次
1006	// 重新处理若保存成功不标回放，此后原样重提才回放已保存的结果。已经成功保存
1007	// 的拒绝仍按首次结果回放，改动该请求的业务内容仍报请求号冲突；必填内容缺失
1008	// 或引用不存在沿用原错误且不占用请求号。
1009	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
1010		missing := []string{}
1011		if strings.TrimSpace(req.Operator) == "" {
1012			missing = append(missing, "operator")
1013		}
1014		if strings.TrimSpace(req.Reason) == "" {
1015			missing = append(missing, "reason")
1016		}
1017		if strings.TrimSpace(req.RequestID) == "" {
1018			missing = append(missing, "request_id")
1019		}
1020		if strings.TrimSpace(req.AuthID) == "" {
1021			missing = append(missing, "auth_id")
1022		}
1023		if len(missing) > 0 {
1024			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1025				ErrInvalidArgument, strings.Join(missing, ", "))
1026		}
1027		r.mu.Lock()
1028		defer r.mu.Unlock()
1029		if err := r.checkOpen(); err != nil {
1030			return ProxyTransferResult{}, err
1031		}
1032	
1033		now := r.now()
1034		key := requestKey(req.Operator, req.RequestID)
1035		sig := proxyTransferParamsSig(req)
1036		if prev, ok := r.state.Requests[key]; ok {
1037			return r.replayProxyTransfer(prev, sig)
1038		}
1039	
1040		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1041			if !isValidationErr(bizErr) {
1042				// 状态类业务拒绝（无权、已撤销、已到期、已使用、停用、版本已
1043				// 变化）占用请求号并落盘：相同参数重提返回这一次拒绝。
1044				r.state.Requests[key] = request{
1045					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1046					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1047				}
1048				if err := r.commit(); err != nil {
1049					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让、授权
1050					// 创建/撤销一致——不能用业务错误掩盖保存错误，调用者稍后用
1051					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际没有
1052					// 保存的拒绝。此分支在写入前只动了请求记录，没有改变持有、
1053					// 授权或版税；commit 失败时已按磁盘内容重建状态，请求记录随之
1054					// 撤销，此处再删一次以覆盖磁盘暂时不可读、状态未能重建的情形。
1055					// 整体返回空结果：不带授权或藏品编号、不带转让和金额信息、不标
1056					// 回放、结果中业务错误为空，error 保留实际写入错误。
1057					delete(r.state.Requests, key)
1058					return ProxyTransferResult{}, err
1059				}
1060			}
1061			// 必填缺失、授权或账户不存在等校验错误不占用请求号，也不改变持有、
1062			// 授权状态或授权变更记录。
1063			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1064		}
1065	
1066		a := r.state.Authzs[req.AuthID]
1067		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1068		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1069		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1070		// 追溯。
1071		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1072		a.Status = "used"
1073		a.UsedTxSeq = out.seq
1074		a.UsedAt = now
1075		r.state.Authzs[a.ID] = a
1076		authSeq := r.state.NextAuthSeq + 1
1077		r.state.NextAuthSeq = authSeq
1078		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1079			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1080			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1081			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1082		})
1083		r.state.Requests[key] = request{
1084			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1085			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1086			Version: out.toVer(), TxSeq: out.seq,
1087		}
1088		if err := r.commit(); err != nil {
1089			return ProxyTransferResult{}, err
1090		}
1091		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1092			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1093			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1094			Remainder: out.royalty.Remainder}, nil
1095	}
1096	
1097	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1098		a, ok := r.state.Authzs[req.AuthID]
1099		if !ok {
1100			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1101		}
1102		op, ok := r.state.Accounts[req.Operator]
1103		if !ok {
1104			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1105		}
1106		granter, gOk := r.state.Accounts[a.GranterID]
1107		to, tOk := r.state.Accounts[a.ToID]
1108		if req.Operator != a.TrusteeID {
1109			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1110				ErrForbidden, req.Operator, req.AuthID)
1111		}
1112		if !gOk {
1113			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1114		}
1115		if !tOk {
1116			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1117		}
1118		if !op.Active {
1119			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1120		}
1121		if !granter.Active {
1122			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1123		}
1124		if !to.Active {
1125			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1126		}
1127		switch authzCurrentStatus(a, now) {
1128		case AuthRevoked:
1129			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1130		case AuthExpired:
1131			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1132		case AuthUsed:
1133			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1134		}
1135		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1136		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1137		h, ok := r.state.Holdings[a.ItemID]
1138		if !ok {
1139			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1140		}
1141		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1142			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1143				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1144		}
1145		return nil
1146	}
1147	
1148	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1149		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1150			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1151				ErrRequestConflict, prev.Operator, prev.RequestID)
1152		}
1153		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1154			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1155		if prev.Rejected {
1156			res.Err = codeErr(prev.Reason)
1157			return res, res.Err
1158		}
1159		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1160		// 原价款与应付明细，不重复计入。
1161		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1162		return res, nil
1163	}
