1167	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1168	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1169	// 到期但尚未终结的授权返回 AuthExpired。
1170	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1171		r.mu.Lock()
1172		defer r.mu.Unlock()
1173		if err := r.checkOpen(); err != nil {
1174			return Authorization{}, err
1175		}
1176		a, ok := r.state.Authzs[authID]
1177		if !ok {
1178			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1179		}
1180		return Authorization{
1181			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1182			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1183			Status:    authzCurrentStatus(a, r.now()),
1184			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1185			RevokedAt: a.RevokedAt,
1186		}, nil
1187	}
