1189	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1190	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1191	// 不存在时返回包裹 ErrNotFound 的错误。
1192	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1193		r.mu.Lock()
1194		defer r.mu.Unlock()
1195		if err := r.checkOpen(); err != nil {
1196			return nil, err
1197		}
1198		if _, ok := r.state.Items[itemID]; !ok {
1199			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1200		}
1201		out := make([]AuthorizationEvent, 0)
1202		for _, e := range r.state.AuthEvents {
1203			if e.ItemID != itemID {
1204				continue
1205			}
1206			out = append(out, AuthorizationEvent{
1207				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1208				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1209				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1210				OccurredAt: e.OccurredAt,
1211			})
1212		}
1213		return out, nil
1214	}
