1217	
1218	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1219	func (r *Registry) GetItem(id string) (Item, error) {
1220		r.mu.Lock()
1221		defer r.mu.Unlock()
1222		if err := r.checkOpen(); err != nil {
1223			return Item{}, err
1224		}
1225		it, ok := r.state.Items[id]
1226		if !ok {
1227			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1228		}
1229		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1230			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1231	}
1232	
1233	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1234	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1235		r.mu.Lock()
1236		defer r.mu.Unlock()
1237		if err := r.checkOpen(); err != nil {
1238			return Holding{}, err
1239		}
1240		h, ok := r.state.Holdings[itemID]
1241		if !ok {
1242			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1243		}
1244		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1245	}
1246	
1247	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1248	// ErrNotFound 的错误；停用账户仍可正常查询。
1249	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1250		r.mu.Lock()
1251		defer r.mu.Unlock()
1252		if err := r.checkOpen(); err != nil {
1253			return nil, err
1254		}
1255		if _, ok := r.state.Accounts[accountID]; !ok {
1256			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1257		}
1258		out := make([]Holding, 0)
1259		for _, h := range r.state.Holdings {
1260			if h.OwnerID == accountID {
1261				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1262			}
1263		}
1264		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1265		return out, nil
1266	}
1267	
1268	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1269	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1270	// 返回包裹 ErrNotFound 的错误。
1271	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1272		r.mu.Lock()
1273		defer r.mu.Unlock()
1274		if err := r.checkOpen(); err != nil {
1275			return nil, err
1276		}
1277		if _, ok := r.state.Items[itemID]; !ok {
1278			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1279		}
1280		out := make([]HistoryEntry, 0)
1281		for _, e := range r.state.History {
1282			if e.ItemID != itemID {
1283				continue
1284			}
1285			out = append(out, HistoryEntry{
1286				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1287				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1288				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1289			})
1290		}
1291		return out, nil
1292	}
1293	
1294	// ---- 幂等辅助 ----
1295	
1296	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1297	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1298	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1299	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1300	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1301	func requestKey(operator, requestID string) string {
1302		b, _ := json.Marshal([2]string{operator, requestID})
1303		return string(b)
1304	}
1305	
1306	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1307	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1308	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1309	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1310	// 并回放。
1311	func isValidationErr(err error) bool {
1312		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1313	}
1314	
1315	var errCodes = map[error]string{
1316		ErrNotFound:             "not_found",
1317		ErrAlreadyExists:        "already_exists",
1318		ErrAccountInactive:      "account_inactive",
1319		ErrSeriesSealed:         "series_sealed",
1320		ErrConflict:             "conflict",
1321		ErrSameAccount:          "same_account",
1322		ErrForbidden:            "forbidden",
1323		ErrAuthorizationRevoked: "authorization_revoked",
1324		ErrAuthorizationExpired: "authorization_expired",
1325		ErrAuthorizationUsed:    "authorization_used",
1326		ErrRoyaltyFrozen:        "royalty_frozen",
1327		ErrSplitIntentRejected:  "split_intent_rejected",
1328		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1329		ErrSplitIntentInvalid:   "split_intent_invalid",
1330		ErrSplitIntentExpired:   "split_intent_expired",
1331		ErrSplitAnswered:        "split_answered",
1332	}
1333	
1334	var codeErrs = map[string]error{
1335		"not_found":              ErrNotFound,
1336		"already_exists":         ErrAlreadyExists,
1337		"account_inactive":       ErrAccountInactive,
1338		"series_sealed":          ErrSeriesSealed,
1339		"conflict":               ErrConflict,
1340		"same_account":           ErrSameAccount,
1341		"forbidden":              ErrForbidden,
1342		"authorization_revoked":  ErrAuthorizationRevoked,
1343		"authorization_expired":  ErrAuthorizationExpired,
1344		"authorization_used":     ErrAuthorizationUsed,
1345		"royalty_frozen":         ErrRoyaltyFrozen,
1346		"split_intent_rejected":  ErrSplitIntentRejected,
1347		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1348		"split_intent_invalid":   ErrSplitIntentInvalid,
1349		"split_intent_expired":   ErrSplitIntentExpired,
1350		"split_answered":         ErrSplitAnswered,
1351	}
1352	
1353	func errCode(err error) string {
1354		for sentinel, code := range errCodes {
1355			if errors.Is(err, sentinel) {
1356				return code
1357			}
1358		}
1359		return "rejected"
1360	}
1361	
1362	func codeErr(code string) error {
1363		if e, ok := codeErrs[code]; ok {
1364			return e
1365		}
1366		return errors.New("registry: 请求曾被拒绝")
1367	}
