64			ExpectedVer   int64  `json:"expected_version"`
65			Price         int64  `json:"price,omitempty"`
66		}
67		entries := make([]entry, 0, len(req.Entries))
68		for _, e := range req.Entries {
69			entries = append(entries, entry{
70				ItemID: e.ItemID, ToID: e.ToID, ExpectedOwner: e.ExpectedOwner,
71				ExpectedVer: e.ExpectedVer, Price: e.Price,
72			})
73		}
74		b, _ := json.Marshal(struct {
75			Kind    string  `json:"kind"`
76			Reason  string  `json:"reason"`
77			Entries []entry `json:"entries"`
78		}{"transfer_batch", req.Reason, entries})
79		return string(b)
80	}
81	
82	// TransferBatch 由持有人一次提交多件藏品，分别转给各自指定的接收账户，
83	// 整批共用操作者、原因与请求号。藏品可来自不同系列与发行批次，接收账户
84	// 可以重复；操作者必须是每件的当前持有人。
85	//
86	// 整批只能全部成功或全部拒绝：全部条目在同一临界区内按清单顺序依次转让，
87	// 各件版本分别加一，历史序号连续，整批记录之间不能插入其他发行或转让；
88	// 版税按各件所属系列首次发行时固定的规则快照分别计算，同一收款账户在
89	// 多件中出现也各自保留明细，不把价款合并后计算；零金额明细与归转让前
90	// 持有人的余款沿用单件转让规则。整批转让不使用任何代转授权，也不把已有
91	// 授权记为已使用；成功转出后，绑定旧版本的授权即使在藏品转回后也不能
92	// 恢复使用。系列封存不阻止转让。
93	//
94	// 空清单、重复藏品编号、必填内容缺失、非正期望版本或负价款按参数错误
95	// 拒绝。每件沿用单件转让的账户登记、停用、收发不同人与持有版本规则；
96	// 多件存在业务拒绝时，返回清单顺序最前的失败藏品及其错误；操作者未
97	// 登记或停用时只返回账户错误（ItemID 为空）。任何拒绝都不改变任何一件
98	// 的持有、版本、历史或应付。
