188	func (r *Registry) checkTransferBatch(req TransferBatchRequest) (string, error) {
189		return r.checkBatchTransferEligibility(req.Operator, req.Entries)
190	}
191	
192	func (r *Registry) replayTransferBatch(prev request, sig string) (TransferBatchResult, error) {
193		if prev.Kind != "transfer_batch" || prev.Params != sig {
194			return TransferBatchResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
195				ErrRequestConflict, prev.Operator, prev.RequestID)
196		}
197		res := TransferBatchResult{ItemID: prev.ItemID, Replayed: true}
198		if prev.Rejected {
199			res.Err = codeErr(prev.Reason)
200			return res, res.Err
201		}
202		// 回放整批首次成功的转让结果：即使藏品后来再次易手、账户停用或进程
203		// 重开，仍返回原前后持有人、版本、序号与原价款/应付明细，不改写当前
204		// 状态，也不重复计入应付。
205		for _, bi := range prev.TransferBatch {
206			price, payables, remainder := r.royaltyOfTx(bi.TxSeq)
207			res.Items = append(res.Items, TransferBatchItem{
208				ItemID: bi.ItemID, FromID: bi.FromID, ToID: bi.ToID, Version: bi.Version,
209				TxSeq: bi.TxSeq, Price: price, Payables: payables, Remainder: remainder,
210			})
211		}
212		return res, nil
